python - <<'PY'
import zipfile
from pathlib import Path
for p in Path('rust-reference/test-files').glob('*.zip'):
    print(p)
    with zipfile.ZipFile(p) as z:
        for i,info in enumerate(z.infolist()):
            print(i, info.filename, info.flag_bits, info.compress_type, info.CRC, info.file_size)
            for pwd in [b'ab',b'abc',b'abcd']:
                try:
                    z.read(info, pwd=pwd)
                    print(' ok',pwd)
                except Exception as e:
                    print(' fail',pwd,type(e).__name__,e)
